scripts.script:
try(def in = org.pdfclown.common.util.io.Resource.of(
    "${buildResourcesDir}/org/pdfclown/common/build/conf/scripts/validate-build.groovy")
    .openStream()) {
  new GroovyShell(binding).evaluate(new InputStreamReader(in))
}

try(def in = org.pdfclown.common.util.io.Resource.of(
    "${buildResourcesDir}/org/pdfclown/common/build/conf/scripts/check-reuse.groovy")
    .openStream()) {
  new GroovyShell(this.class.classLoader, binding).evaluate(new InputStreamReader(in))
}

import org.pdfclown.common.build.util.system.Builds

/*
  TODO: remove 'Bootstrap' conditional branch when next (0.9.0) pdfclown-common version is bumped,
  and replace all other explicit `GroovyShell` invocations with new `Builds.runScript`.
 */
if (Builds.respondsTo('runHook')) {
  Builds.runScript("${buildResourcesDir}/org/pdfclown/common/build/conf/scripts/" +
      "init-build-info.groovy", binding)
  Builds.runScript("${buildResourcesDir}/org/pdfclown/common/build/conf/scripts/" +
      "init-checkstyle.groovy", binding)
}
// Bootstrap (0.8.0).
else {
  new GroovyShell(this.class.classLoader, binding).evaluate(new File(
      "${buildResourcesDir}/org/pdfclown/common/build/conf/scripts/init-build-info.groovy"))
  new GroovyShell(this.class.classLoader, binding).evaluate(new File(
      "${buildResourcesDir}/org/pdfclown/common/build/conf/scripts/init-checkstyle.groovy"))
}

try(def in = org.pdfclown.common.util.io.Resource.of(
    "${buildResourcesDir}/org/pdfclown/common/build/conf/scripts/pick-jar-licenses.groovy")
    .openStream()) {
  new GroovyShell(this.class.classLoader, binding).evaluate(new InputStreamReader(in))
}

try(def in = org.pdfclown.common.util.io.Resource.of(
    "${buildResourcesDir}/org/pdfclown/common/build/conf/scripts/pack-shaded-notice.groovy")
    .openStream()) {
  new GroovyShell(binding).evaluate(new InputStreamReader(in))
}

try(def in = org.pdfclown.common.util.io.Resource.of(
    "${buildResourcesDir}/org/pdfclown/common/build/conf/scripts/pick-jar-licenses.groovy")
    .openStream()) {
  new GroovyShell(this.class.classLoader, binding).evaluate(new InputStreamReader(in))
}
